:root {
  --color-bg: #F6F7F9;
  --color-surface: #FFFFFF;
  --color-surface-muted: #EEF1F4;
  --color-border: #D5DAE1;
  --color-text: #0F1B2D;
  --color-text-muted: #475467;
  --color-text-inverse: #FFFFFF;
  --color-header-bg: #0F1B2D;
  --color-header-text: #FFFFFF;
  --color-primary: #0F766E;
  --color-primary-hover: #0B5F59;
  --color-primary-text: #FFFFFF;
  --color-danger: #B42318;
  --color-danger-hover: #912018;
  --color-danger-bg: #FEE4E2;
  --color-success: #166534;
  --color-success-bg: #DCFCE7;
  --color-warning: #92400E;
  --color-warning-bg: #FEF3C7;
  --color-info: #1E40AF;
  --color-info-bg: #DBEAFE;
  --color-focus: #1D4ED8;
  --color-status-pending-bg: #FEF3C7;
  --color-status-pending-text: #92400E;
  --color-status-confirmed-bg: #DCFCE7;
  --color-status-confirmed-text: #166534;
  --color-status-cancelled-bg: #FEE4E2;
  --color-status-cancelled-text: #991B1B;
  --color-status-completed-bg: #DBEAFE;
  --color-status-completed-text: #1E40AF;
  --color-status-unavailable-bg: #E4E7EC;
  --color-status-unavailable-text: #344054;

  --font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-md: 1rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.625rem;
  --font-size-2xl: 2.125rem;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;
  --line-height: 1.5;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-pill: 999px;

  --shadow-card: 0 1px 2px rgba(15,27,45,0.08), 0 2px 8px rgba(15,27,45,0.06);
  --shadow-raised: 0 8px 24px rgba(15,27,45,0.14);

  --width-content: 1200px;
  --width-narrow: 720px;
  --width-form: 640px;
  --width-card-min: 280px;
  --width-booking-panel: 380px;

  --control-height: 44px;
  --control-height-sm: 36px;

  --breakpoint-sm: 480px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-family);
  font-size: var(--font-size-md);
  line-height: var(--line-height);
  background: var(--color-bg);
  color: var(--color-text);
}

img {
  max-width: 100%;
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

